"""Stage 3 merge for report 33."""
import json
C = {x["id"]: x for x in json.load(open("Tools/prd_ledger/canonical.json"))}
def ext(cid, text):
    if text not in C[cid]["statement"]: C[cid]["statement"] += text
def add(cid, section, title, statement):
    if cid in C: return
    C[cid] = dict(id=cid, title=title, statement=statement, section=section, cards=[], reports=[], merged_from=[])

add("C249","must-never-break","Account deletion completes in one step, in-app and on the web, and is confirmed — never a spinner or a silent chatbot","Report 33: account deletion that spins forever drew 47 reviews (1.19%) at mean 1.23 — zero 5★, 41 1★, the worst-rated theme in a 3.74★ corpus — 23 of them in 2020 and still reported in 2025, 16 from Korea (5.5% of that storefront): users who wanted to switch apps found support silent ('emails keep coming, so I can't uninstall'), the app crashed on delete, 'once you ask the chat bot … it stops answering'; 'Did you choose to block account deletion to keep customers?'; 'I trust it isn't deliberate… but inflating users this way looks bad'. It reads as dark-pattern retention, carries data-subject-deletion exposure, and is among the cheapest fixes relative to its reputational cost.")
add("C250","must-never-break","Marketing e-mail needs consent and a working one-tap unsubscribe — never e-mail dormant or deleted accounts","Report 33: in July 2023 (28 Jun – 31 Aug: 59 reviews, mean 2.88; 9 on 5 July alone, mean 1.67) users who had not opened the app for one to two years, or had deleted their account, received daily 'habit' e-mails with no working unsubscribe — 37 marketing-email reviews (0.94%, mean 1.41, 81.1% 1★), 27 in 2023 (12.7% of that year), six of Germany's seven from the wave: 'They probably do this on purpose to inflate their active user stats'; 'daily spam messages that contain all my data … I'll report them to the ICO for breaching GDPR'; CAN-SPAM cited. An unsubscribe link added quickly after the complaints cut the theme to 0.1% of later reviews, but a privacy professional still found it broken in May 2024 ('this is simply embarassing'). Honour deletion across every marketing system.")
add("C251","product-rule","If cross-platform is what people buy, ship every platform in parity — same release, same entitlement, or a visible 'coming' state","Report 33: one account across iPhone, iPad, Watch, Mac, web, Android and Windows is a top purchase trigger (106 cross-platform praise reviews rated 4–5★; 'since I get Mac OS, iPad, and Apple Watch apps all for one subscription … I'm fine with it'; 'signed up for premium mainly because this has a web interface') and the top engineering complaint of 2020–23 — platform issues 354 (8.99%, mean 2.87), 18.7% of E3 and 19.9% of E4; the Mac app stalled for a year ('left for a year at a time'; support: 'the update version is only released on phone, not the MacOS yet'), Mac/web reached 12.2% of E4 and fell to 2.2% after the macOS 13.0.1 fix; entitlements did not follow the person across web (Paddle) → iPhone, guest → account or a new phone (~25 cases, some taking 6+ weeks). Cross-platform wins sales and loses stars unless every device ships on the same day with one entitlement.")

ext("C001", " Report 33: the gate tightened in steps — one-time Premium replaced by subscription (17 Jan 2019; price objection 9.4% of 2019, subscription objection 29 in 2019; a buyer two days earlier got one year), notes (with 300 days of history), skip, multiple reminders, dark mode and history beyond 30 days moved to Premium (Apr 2019), a 15-per-week check-in cap (Oct 2020), and the free tier cut to 2 habits (2025–26, cap 9.3% of 2026, 'slowly chipping away at the most basic features') — the spikes in 1★ follow each take-back rather than the cap; 18 reviewers defend the cap and 48 call the free tier sufficient.")
ext("C002", " Report 33: the eight worst-rated themes are about leaving, being contacted, being billed or being ignored (account deletion 1.23, privacy 1.35, marketing e-mail 1.41, cannot cancel 1.62, support failure 1.70) and none is a missing feature; the free cap (2.31) and price objection (2.64) are milder — people tolerate a gate, not being trapped, spammed or charged for nothing; the praised qualities (simplicity, design, cross-platform, lifetime) are what the 1–2★ reviews say was lost.")
ext("C003", " Report 33: a lifetime option restored in Apr 2019 alongside monthly and annual is the most-cited purchase trigger (112 payers, mean 3.62; 'Habitify allows you to unlock all premium features with a 1 time in-app purchase of $10'; 'you'll pay double in a year for some other similar apps'); E2, when lifetime coexisted with a stable app, is the payer high (mean 3.77) and price praise never fell (1.9% → 3.2%) — rivals that only rent are named as the reason people chose Habitify; the report says keep it and publish what lifetime includes.")
ext("C004", " Report 33: 99 price-praise reviews (mean 4.85, zero 1★) — 'permanent premium is only equal to other apps' annual fee'; 'I would have paid triple'; 'the best £30 I ever spent'.")
ext("C005", " Report 33: 217 competitor mentions (5.51%, mean 4.31, 152 5★) and Habitify is mostly the destination — arrivals from Productive, Way of Life, HabitBull, Strides, Momentum, Done, Notion, Streaks; departures to Streaks (one-time price, iCloud sync, better Health, 'a tenth of the price'), TickTick, Loop (free), Fabulous, Atoms.")
ext("C006", " Report 33: simplicity praise fell 15.9% (E1) → 6.0–7.3% as goals, timer, Health, mood, challenges, friends and AI accumulated, while 'confusing / hard to use' tripled to 5.8% of E5 ('None of the over-designed … gamification' was once the praise); the report recommends 'simple mode' defaults that hide friends, challenges and journal until enabled.")
ext("C007", " Report 33: a 3-habit cap (sometimes 2) draws 213 complaints (5.41%, mean 2.31) — 'isn't much of a test run'; 'if … 5 rather than 3 … I'd have … probably upgraded' — but is far milder than the take-backs; the report proposes testing 3 habits + unlimited check-ins vs 5 habits vs a 14-day full trial; Spain, the UK and Brazil show the highest cap rates (10.5–10.7%).")
ext("C011", " Report 33: statistics praised by 182 rated 4–5★ ('The statistics … is what sold me') and a named purchase trigger; 58 request an all-habit weekly grid, raw totals and multi-year history ('I want a GitHub type chart'); yearly and daily-ratio stats were removed in Habitify X.")
ext("C013", " Report 33: one purchase covering iPhone, iPad, Watch, Mac, web, Android and Windows is a leading purchase trigger — and every platform that lagged became a support case (see C251).")
ext("C014", " Report 33: multiple reminders per habit were moved to Premium in 2019 and cited as a paid feature buyers value ('With the premium subscription, I can add multiple reminders').")
ext("C015", " Report 33: challenges, friends and sharing (2022+) are mixed (challenges 19, some gated), and the report recommends hiding them until enabled.")
ext("C016", " Report 33: pause / vacation mode never existed (18 requests; a 'reschedule' swipe) — the report asks for a pause that preserves streaks.")
ext("C017", " Report 33: the passcode lock was removed in 2025, a lifetime holder's complaint.")
ext("C018", " Report 33: per-habit colours and themes requested by 48 ('I dislike blue … would pay more').")
ext("C019", " Report 33: bad-habit / limit tracking done well requested by 23 — a tap per cigarette, auto-fail over the limit.")
ext("C020", " Report 33: CSV export was removed with Habitify X (Aug 2020) and back from 2022.")
ext("C021", " Report 33: Apple Health auto-logging and Fitbit, Strava, screen-time and NFC habits, described as both free and Premium; Health integration complaints rose to 2.2% of E5 and Garmin / wearable auto-completion is requested.")
ext("C022", " Report 33: the Watch app broke with iOS 13, would not launch after Habitify X, its complication broke with iOS 15.1 and sync lagged until 'finally' fixed Jan 2024 — 100 reviews (2.84 mean), 6.8% of E3, Japan 5.0% ('Streaks costs a tenth and works'); single-tap logging and area complications were removed.")
ext("C023", " Report 33: the 2016 Today widget was removed ('the entire reason I paid'), iOS 14 widgets were non-interactive, and the May 2025 redesign removed compact, incremental (+1) and streak widgets — widget complaints 6.3% of 2025, the one surface still worsening; interactive widgets named as the 4★ → 5★ piece.")
ext("C024", " Report 33: motivation / streaks praised by 130 (mean 4.75); non-daily streaks broke and the streak count on the complete button changed in redesigns.")
ext("C027", " Report 33: localisation grievances are about quality — 「たどたどしい日本語」 (halting Japanese), simplified-Chinese glyphs in Japanese, an offensive German UI string ('Pisst du dabei?'), a lost Russian UI, English-only support replies — 62 reviews (1.57%); Chinese reviewers praise the localisation; Arabic users ask for an Arabic UI; motivational copy read as 'far too American and over the top' in the Netherlands.")
ext("C029", " Report 33: billing integrity 147 (3.73%, mean 2.22) — charged more than shown (¥4,900 shown, ¥5,150 charged; a $39.99 offer charged $48.97; monthly chosen, annual charged; lifetime then an annual charge); billing-dispute register 「詐欺アプリ」, 'Abzocke', 'CON ARTISTS', 流氓.")
ext("C030", " Report 33: account-only (Firebase) sync replaced personal iCloud sync ('Original Habitify was able to sync … over personal iCloud. This has been removed'), with repeated logouts; sync failures 119 (3.02%), 7.9% of E4 — offer iCloud sync as an option alongside the account backend.")
ext("C031", " Report 33: an 11 Sep 2025 'Liquid glass' update crashed on launch on iOS 18 and was fixed in ~1–3 days with no lasting rating shift; in Oct–Nov 2019 Brazilian users could not open the app after purchase.")
ext("C033", " Report 33: entitlement failure is small (69, 1.75%) and mostly portability — web (Paddle) purchases not unlocking the iPhone, a lifetime tied to one e-mail and paid twice, guest → account, a new or stolen phone, 18 days without activation, 6+ weeks and 20+ e-mails to resolve, a lifetime holder asked to subscribe on the Watch — plus a Jan 2018 wave (21, 11 in Japan) fixed within two weeks; the report asks for one entitlement per person recognised on every platform, with guest and account purchases merged automatically.")
ext("C034", " Report 33: v2.0 (Nov 2016) wiped history and Premium for many ('30 routines gone'); Habitify X erased 4 months of time logs; data lost 55 reviews (mean 2.25).")
ext("C035", " Report 33: guest mode is a data trap — 26 users who never created an account lost everything on update, reinstall or Mac sign-in ('Never use guest mode'; a ¥6,000 lifetime bought as a guest) — while forced login since 2016 is itself a privacy complaint.")
ext("C036", " Report 33: support is two-sided — praised 103 (mean 4.73; 'Hana … sent me a video'; 'within one minute') vs support failure 131 (1.70; 5 weeks without reply then the review deleted); English-only replies frustrate Japanese and Chinese users; AI-only support is an emerging negative (8 reviews, 7 in 2025–26: 'Their support is AI'; the chatbot 'stops answering').")
ext("C037", " Report 33: a paid family plan (2025) whose sharing is described as not working (7, mean 2.00).")
ext("C039", " Report 33: reminders praised by 91 (repeat every 30 min until done) and broken in 68, notably when iOS 13 broke notifications.")
ext("C042", " Report 33: ADHD, neurodivergent and health users praise the structure ('as an adult with ADHD'; 'I'm neurodivergent and I really hate routine'; medication) and object most clearly to guilt copy and unclosable banners ('I have adhd … huge banner … you CAN NOT CLOSE').")
ext("C043", " Report 33: 'N times a week' and every-N-days frequency are named differentiators (flexible scheduling praised 79, mean 4.80); 'N per week' was removed in Habitify X and restored; monthly nth-weekday and end dates are still requested (82; haircut, bills on the 15th, can't end a 30-day challenge).")
ext("C044", " Report 33: a Mac app (sold separately in 2018), a menu-bar mini app, web, Android and Windows exist; the Mac app could not sign in or sync through 2021–22 (Mac/web 18.5% of 2022, Russia 10.1%) until macOS 13.0.1.")
ext("C045", " Report 33: areas / folders (Dec 2019) are free and mixed (31).")
ext("C046", " Report 33: x-callback / Shortcuts, Zapier / IFTTT, a public API, calendar sync and NFC habits serve power users (47, rising to 2.5% of E5; API 'unbeatable'; 'Pairs nicely with agentic workflows'); Siri Shortcuts broke in Habitify X.")
ext("C048", " Report 33: goals with units and multiple check-ins per day shipped in Aug 2020; custom units (kg, kcal, metric) and icons still requested (56).")
ext("C049", " Report 33: a mood log (Aug 2021) with multiple moods per day as Premium — 14 mentions, mixed.")
ext("C050", " Report 33: one-off tasks requested by 10.")
ext("C053", " Report 33: time-of-day sections (morning / afternoon / evening / anytime) are a named differentiator — 'no other app does as well'; 'the best thing about Habitify' — and paired with flexible frequency form 'a winning core'; a hidden time-of-day filter also produced false bug reports.")
ext("C054", " Report 33: review solicitation — a founder-named 5★ burst (12 Oct – 1 Nov 2018: 110 reviews at mean 4.64 vs 3.30 before), 'a strange email … asking for a rating', a free-lifetime link after reviewing, contests awarding Premium, and a CEO asking for 5★ — 'Who the hell is peter?'; the burst left no durable effect and the report's last cheapest win is to stop it.")
ext("C055", " Report 33: one unverified claim that the developer deleted a review after 5 weeks without support.")
ext("C056", " Report 33: AI 'smart fill' and AI / chatbot support (2025–26) drew mostly negative reviews — 'Stop shoving AI everywhere'.")
ext("C059", " Report 33: fast fixes after a review earn thanks and rating rises ('thank you for responding right after my review'; a 1★ raised to 4★ after a fix); a public roadmap and feature voting; the Jan 2018 purchase wave fixed in two weeks and the Sep 2025 launch crash in 1–3 days; 'An update improved it' 112 (mean 4.78).")
ext("C061", " Report 33: supporting a small team was a purchase trigger ('I can see this team cares'); 48 call the free tier sufficient (mean 4.85); Vietnamese reviewers take pride in a Vietnamese-built app.")
ext("C062", " Report 33: high-spend storefronts rate lower (3.60 vs 3.93; ≈3.70 without China) and differ in what money buys — 1.6× payers, 3× Premium not granted, 2.3× billing integrity — with price objection identical (5.2%); the 81-storefront tail rates higher and pays less (3.89 vs 3.71).")
ext("C063", " Report 33: for most of the corpus there was no trial ('Three habits, and three days, is simply too little'), and purchase intent 'would buy if…' appears in 44.")
ext("C064", " Report 33: price objection 203 (5.15%, mean 2.64), highest in Germany (14.7%), Turkey (10.5%) and France (10.4%) — '269 roubles … I pay 400 for Netflix'; '43 euro … for an agenda???'; '€40 … vous vivez où, Monaco?'.")
ext("C065", " Report 33: 427 explicit payers (10.84%, mean 3.16) are polarised — 212 rate 4–5★, 172 rate 1–2★; their mood tracks integrity events, not price (E2 3.77 with a stable lifetime app; 2018 2.83 with 25 purchases not applied; E3 2.78 after Habitify X); after paying: reliability 42.6%, integrity 26.7%, support failure 11.9%, regressions 11.5%; nearly one 1★ in five is a payer.")
ext("C067", " Report 33: life outcomes 205 (on the way to 100 books; out of depression; quitting smoking; 1,000+ gym days); medical / mental-health use 20 (mean 4.70).")
ext("C072", " Report 33: Health sleep double-counting and data wiped when switching tracking mode — de-duplicate, allow manual override.")
ext("C073", " Report 33: custom ordering that sticks requested / broken in 47 (90 routines; broken in v10.7.4–10.7.5 and again in 2026).")
ext("C080", " Report 33: dark mode and themes were Premium in 2019–20; 48 request themes / colours.")
ext("C092", " Report 33: regional price objections from Vietnam, Turkey (270 TL), Korea ('I'll buy if it's discounted') and Japan (¥19,000 lifetime, 'unfair to base your pricing on [exchange rates] alone'; 「前に比べて値段が爆上がり」) — regionalise lifetime pricing.")
ext("C094", " Report 33: in-app rating prompts 'three in 10 seconds' (Nov 2017 – Jan 2018) made review-nag complaints 3.8% of 2017 before falling to ≤1% every later year; 82 of 88 rating-contradicts-text reviews are 5★ reporting a bug or block; 820 short reviews (20.8%) inflate the positive side.")
ext("C095", " Report 33: guilt copy backfires — 'Let's do better tomorrow, shall we?'; 'Yikes'; a Jan 2026 'Are you sure the day is over?' pop-up on fail/skip with no off switch ('infantilizing … Shipping annoying stuff without an off switch is a churn risk') — 43 reviews on unwanted or guilt notifications (mean 2.33).")
ext("C096", " Report 33: privacy 23 reviews (mean 1.35) — the in-app help showed other customers' support conversations, e-mails and photos; goal-share URLs readable without login with no off switch; sync requiring Apple ID, Google account and e-mail; third-party analytics — audit support-conversation scoping and make sharing opt-in with unguessable, expiring links.")
ext("C104", " Report 33: Habitify X (~27 Aug 2020) removed time logs, yearly stats, CSV export, swipe, 'N per week', Shortcuts and the Watch app with 'no migration path' — 149 reviews in nine weeks, 42 UPDATE-.")
ext("C109", " Report 33: 2025–26 trials converted to an annual charge unexpectedly ('I signed up for a free trial and somehow got converted to paid'; 'a 7- or 14-day trial, then charged a full year of Pro').")
ext("C112", " Report 33: web-billed (Paddle) subscriptions had no in-app cancel ('payments … through a third party and there's no unsubscribe button'), 13 cannot-cancel reviews at mean 1.62; a deleted account was still charged; cancelling a renewal after a trial ended current access — show renewal date, price and a cancel link for every billing channel, and keep access through the paid period.")
ext("C113", " Report 33: charged more than shown in ~6 cases (¥4,900 → ¥5,150; $39.99 → $48.97; monthly chosen, annual charged).")
ext("C132", " Report 33: a mandatory account backend unreachable from mainland China made the app unusable there for eight years — 173 reviews (4.39%; 57.8% of China; 79 of its 101 1★), 18 payers who could not use or restore what they bought (328 RMB lifetime, refunds refused), and an App Store 'Today' feature in Dec 2018 that sent 68 Chinese users into a registration failure ('can't register — and you recommended it on the home page?'); China was lost on reachability, not fit — reviewers praised the design and localisation and asked to pay ('I'd pay 188 RMB lifetime if you fixed the server').")
ext("C141", " Report 33: iPad layout with landscape shipped Apr 2019; widgets did not refresh on iPad for years.")
ext("C142", " Report 33: misunderstandings rise with feature count — a time-of-day filter hid habits and produced a false bug report; how to reorder or delete; skip vs cancel vs fail; 'every day starts skipped' (a setting); where the timer is; how to connect the Watch.")
ext("C143", " Report 33: multiple completions per day / quantities (water ×8, pills ×3) was the largest 2017–19 request (53, 50 before Aug 2020) and shipping multi-check-in goals in Habitify X retired it (2.9% of E1 → 0.1% of E5).")
ext("C147", " Report 33: 'Three habits, and three days, is simply too little'; the evaluation argument is the plurality of monetisation objections; 44 say 'would buy if…'.")
ext("C150", " Report 33: prompts 'three in 10 seconds' in 2017–18.")
ext("C155", " Report 33: removals came in release-shaped spikes — v2.0 charity points and data (2016), skip and Russian UI (2017), notes/skip to Premium (2019), Habitify X (2020), notes back-dating and editing (Dec 2024 – Jan 2025), compact/incremental/streak widgets (May 2025), passcode lock (2025) — regression 197 (5.00%, mean 2.51), 14.9% of E3; 2★ is the 'I used to love it' band (regression 15.1%, churn 12.2%); every removal needs a toggle or a migration.")
ext("C157", " Report 33: an 'Are you sure the day is over?' confirmation on fail/skip with no off switch.")
ext("C163", " Report 33: a monthly plan missing in some storefronts or offered only on the web ('only … yearly and lifetime … I would have signed up for a month'; 'pagar 50-60€ como única opción?') — offer monthly in-app everywhere.")
ext("C171", " Report 33: memo input breaks under Japanese IME.")
ext("C172", " Report 33: per-habit per-day notes / journal moved to Premium in Apr 2019 (free users lost 300 days of notes) and in Dec 2024 – Jan 2025 lost back-dating and editing (1,000+ gym days logged in memos).")
ext("C175", " Report 33: v2.0 (Nov 2016) wiped data and Premium; Habitify X broke the Watch; 'update made it worse' spiked 7.6% in 2020 and 5.8% in 2025.")
ext("C176", " Report 33: a weekly check-in cap locked free users out of long streaks ('After 500 days I was pay-walled').")
ext("C186", " Report 33: a lifetime purchase is a bet on continuity — hostile lifetime reviews are about removals, not price ('I paid for the lifetime subscription because the old app was exactly what I wanted. It never occurred to me that they would update it and actually remove things … I wish I had got the monthly subscription so I could cancel'); the 2019 switch converted a £9.99 buyer from two days earlier to one year; a lifetime model obliges the developer to migrate, not delete.")
ext("C200", " Report 33: a free-tier cap of ~15 check-ins per week (Oct 2020 → 2024) drew 29 reviews at mean 2.00 — the worst-rated monetisation mechanism, 4.2% of E3 — and punished the most engaged free users ('three habits is reasonable. The problem … I can't check into those habits more than 15 times a week'; 'limiting the number of check ins per week ruins the whole point').")
ext("C207", " Report 33: hide friends, challenges and journal until enabled — 'simple mode' defaults.")
ext("C210", " Report 33: web purchases through Paddle did not unlock the iPhone (18 days; 6+ weeks) and had no in-app cancel; refunds were routed to Apple and then refused ('denied a refund due to the company's arrangement with Apple').")
ext("C212", " Report 33: refunds routed to Apple, then refused — a child's 598 RMB refused twice; 45 refund reviews (mean 2.16), 13 from Korea.")
ext("C218", " Report 33: 'you finally mention that habits are limited … after they've created it'; 34 price-hidden / misleading 'free' reviews.")
ext("C231", " Report 33: storefronts differ sharply — cn blocked (57.8%), de subscription-averse (price 14.7%, subscription 9.2%), kr the account-deletion centre (5.5%), jp highest payer share (16.0%) and Watch / update complaints, ru Mac/web 10.1%, vn happiest (4.61).")
ext("C236", " Report 33: the habit limit was announced only after users created habits.")
ext("C248", " Report 33: cross-promotion ads for the developer's other apps (Nirow, Poly) shown to lifetime payers — 'False advertisement – Still get ads with lifetime premium'; a premium user shown notices: 'No. deal with it'; 'I wish the upgrade button would disappear when you buy premium' — 14 + 12 reviews.")
ext("C145", " Report 33: a full-screen offer on every open and a banner covering the third habit that cannot be closed (2023–26; upsell 1.7% of E5).")

